<?php if($recent): ?><section class="history" data-flight-tab-content<?= $activeTab !== 'flight' ? ' hidden' : '' ?>><small>RECENT SEARCHES</small><h2>最近の検索</h2><div class="cards"><?php foreach($recent as $recentSearch): ?><button type="button" class="recent-search-card" data-origin="<?= $h($recentSearch['origin']) ?>" data-destination="<?= $h($recentSearch['destination']) ?>" data-departure-date="<?= $h($recentSearch['departure_date']) ?>" data-return-date="<?= $h($recentSearch['return_date'] ?? '') ?>" data-travelers="<?= $h($recentSearch['travelers']) ?>"><b><?= $h($recentSearch['origin']) ?> → <?= $h($recentSearch['destination']) ?></b><span><?= $h($recentSearch['departure_date']) ?><?= !empty($recentSearch['return_date'])?' 〜 '.$h($recentSearch['return_date']):'' ?>・<?= $h($recentSearch['travelers']) ?>名</span></button><?php endforeach ?></div></section><?php endif ?>
